}

"""Calculating boxboundary offsets for each segment"""
def bounding_box_to_offsets(bbox: Any, transform: Any) -> object {
    col1 = int(((bbox[0] - transform[0]) / transform[1]));
    col2 = int(((bbox[1] - transform[0]) / transform[1])) + 1;
    row1 = int(((bbox[3] - transform[3]) / transform[5]));
    row2 = int(((bbox[2] - transform[3]) / transform[5])) + 1;
    return [row1, row2, col1, col2];
}

"""
	eta( r_net_day, evaporative_fraction, temperature)
	"""
def eta(r_net_day: Any, evaporative_fraction: Any, temperature: Any) -> object {
    t_celsius = temperature - 273.15;
    latent = 86400.0 / ((2.501 - (0.002361 * t_celsius)) * pow(10, 6));
    result = r_net_day * evaporative_fraction * latent;
    return result;
}

""" pseudo-paginate a document by creating lists of tokens of length `target-length` that overlap at 50%

    return a list of `target_length`-length lists of tokens, overlapping by 50% representing all the tokens in the document
    """
def overlap(document_tokens: Any, target_length: Any) -> object {
    overlapped = [];
    cursor = 0;
    while (len(' '.join(document_tokens[cursor:]).split()) >= target_length) {
        overlapped.append(document_tokens[cursor:(cursor + target_length)]);
        cursor += target_length // 2;
    }
    return overlapped;
}

"""Returns relevant BERT dataset name, depending on whether we are using a cased model.

    Parameters
    ----------
    is_cased: bool
        Whether we are using a cased model.

    Returns
    -------
    str: Named of the BERT dataset.

    """
def get_bert_dataset_name(is_cased: Any) -> object {
    if is_cased {
        return 'book_corpus_wiki_en_cased';
    } else {
        return 'book_corpus_wiki_en_uncased';
    }
}

